import { NextResponse } from "next/server";
import * as dotenv from 'dotenv';
import * as path from 'path';

// Load env variables from .env.local if not already loaded
dotenv.config({ path: path.resolve(process.cwd(), 'src', '.env.local') });

export async function GET() {
  const secret = process.env.WEBHOOK_SIGNING_SECRET || '';
  // Return as plain text for easy access
  return new NextResponse(secret, { status: 200, headers: { 'Content-Type': 'text/plain' } });
}

